<?php $paragraphs = preg_split('/\n\s*\n/', trim((string) $page['content'])) ?: []; ?>
<section class="section-space"><div class="page-shell max-w-4xl"><div class="max-w-3xl"><p class="eyebrow"><i class="ph ph-file-text" aria-hidden="true"></i><span>OEMS information</span></p><h1 class="section-title mt-4"><?= e($page['title']) ?></h1></div><article class="dashboard-panel mt-8 space-y-5 text-base leading-8 text-[var(--ink-muted)]"><?php foreach ($paragraphs as $paragraph): ?><?php if (trim($paragraph) !== ''): ?><p><?= nl2br(e(trim($paragraph)), false) ?></p><?php endif; ?><?php endforeach; ?></article></div></section>
